WITH with_windows AS (SELECT *, FIRST_VALUE(cost) IGNORE NULLS OVER (PARTITION BY brand ORDER BY price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_cost, DENSE_RANK() OVER (PARTITION BY YEAR(launch_date), category ORDER BY price) AS price_dense_rank, ROW_NUMBER() OVER (PARTITION BY DATE_TRUNC('month', launch_date) ORDER BY cost, id) AS event_seq FROM products) SELECT id, category, brand, price, cost, tags, first_known_cost, price_dense_rank, event_seq FROM with_windows ORDER BY price_dense_rank DESC NULLS FIRST
